import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DPaNRfRs.js";var i=JSON.parse(`{"title":"Interface: ChatComposerState","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://sqlrooms.org/api/ai-core/interfaces/ChatComposerState.html"}]]},"headers":[],"relativePath":"api/ai-core/interfaces/ChatComposerState.md","filePath":"api/ai-core/interfaces/ChatComposerState.md"}`),a={name:`api/ai-core/interfaces/ChatComposerState.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /api/ai-core/interfaces/ChatComposerState.md for this page in Markdown format</div><p><a href="./../">@sqlrooms/ai-core</a> / ChatComposerState</p><h1 id="interface-chatcomposerstate" tabindex="-1">Interface: ChatComposerState <a class="header-anchor" href="#interface-chatcomposerstate" aria-label="Permalink to “Interface: ChatComposerState”">​</a></h1><p>Normalized composer state and actions, identical in shape across both chat runtime modes.</p><p>Read via <a href="./../variables/useChatComposer.html">useChatComposer</a>. This is the behavior layer: it carries no DOM and no styling, and is the supported integration point for a prompt input that is not textarea-shaped (see <code>Input</code>&#39;s tsdoc for the textarea-shaped contract that primitive is limited to).</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="mode" tabindex="-1">mode <a class="header-anchor" href="#mode" aria-label="Permalink to “mode”">​</a></h3><blockquote><p><strong>mode</strong>: <a href="./../type-aliases/ChatComposerMode.html"><code>ChatComposerMode</code></a></p></blockquote><p>Which runtime this state was sourced from.</p><hr><h3 id="prompt" tabindex="-1">prompt <a class="header-anchor" href="#prompt" aria-label="Permalink to “prompt”">​</a></h3><blockquote><p><strong>prompt</strong>: <code>string</code></p></blockquote><p>The current prompt text. In session mode this reads from the active session when one exists, and from the shared draft prompt otherwise, so a suggestions list and the composer always agree before a session is created.</p><hr><h3 id="setprompt" tabindex="-1">setPrompt <a class="header-anchor" href="#setprompt" aria-label="Permalink to “setPrompt”">​</a></h3><blockquote><p><strong>setPrompt</strong>: (<code>value</code>) =&gt; <code>void</code></p></blockquote><p>Updates the prompt in whichever store currently backs it.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string</code></td></tr></tbody></table><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="send" tabindex="-1">send <a class="header-anchor" href="#send" aria-label="Permalink to “send”">​</a></h3><blockquote><p><strong>send</strong>: (<code>text?</code>) =&gt; <code>void</code></p></blockquote><p>Sends the current prompt, or <code>text</code> when provided instead. A no-op when sending is not currently possible (see <a href="#cansend">canSend</a>).</p><p>Registered pre-send vetoes are consulted first (see <a href="./../functions/useRegisterBeforeSend.html">useRegisterBeforeSend</a>). In session mode a session is created if none is active, after the vetoes pass.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th></tr></thead><tbody><tr><td><code>text?</code></td><td><code>string</code></td></tr></tbody></table><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="cancel" tabindex="-1">cancel <a class="header-anchor" href="#cancel" aria-label="Permalink to “cancel”">​</a></h3><blockquote><p><strong>cancel</strong>: () =&gt; <code>void</code></p></blockquote><p>Cancels the in-flight run, if any. A no-op when nothing is running.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="cansend" tabindex="-1">canSend <a class="header-anchor" href="#cansend" aria-label="Permalink to “canSend”">​</a></h3><blockquote><p><strong>canSend</strong>: <code>boolean</code></p></blockquote><p>True when <a href="#send">send</a> would currently do something: a model is resolvable, the prompt is non-empty once trimmed or an attachment is pending, and nothing is already running or summarizing.</p><hr><h3 id="isrunning" tabindex="-1">isRunning <a class="header-anchor" href="#isrunning" aria-label="Permalink to “isRunning”">​</a></h3><blockquote><p><strong>isRunning</strong>: <code>boolean</code></p></blockquote><p>True while a response is being generated.</p><hr><h3 id="isbusy" tabindex="-1">isBusy <a class="header-anchor" href="#isbusy" aria-label="Permalink to “isBusy”">​</a></h3><blockquote><p><strong>isBusy</strong>: <code>boolean</code></p></blockquote><p>True while the composer should present as busy for any reason — currently running, or (session mode only) summarizing the conversation.</p><hr><h3 id="needsapikey" tabindex="-1">needsApiKey <a class="header-anchor" href="#needsapikey" aria-label="Permalink to “needsApiKey”">​</a></h3><blockquote><p><strong>needsApiKey</strong>: <code>boolean</code></p></blockquote><p>True when an API key must be supplied before sending can succeed.</p><p>Always <code>false</code> in local-agent mode, and in session mode when a custom-model factory supplies its own credentials (see the slice&#39;s <code>requiresApiKey</code>).</p><hr><h3 id="sendblocked" tabindex="-1">sendBlocked <a class="header-anchor" href="#sendblocked" aria-label="Permalink to “sendBlocked”">​</a></h3><blockquote><p><strong>sendBlocked</strong>: <code>boolean</code></p></blockquote><p>True while a surface has blocked sending outright (credential entry, say). Already folded into <a href="#cansend">canSend</a>; read directly for controls that carry their own text.</p>`,57)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};